BEGIN;

-- One current position per profile and exact target.
CREATE TABLE "ProgressPositionTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "ProgressPositionTypes" ("Id", "Key") VALUES (1, 'Time'), (2, 'Reading'), (3, 'Game');

CREATE TABLE "MediaProgress" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "WorkId" bigint NOT NULL REFERENCES "Works" ("Id") ON DELETE CASCADE,
    "WorkUnitId" bigint NULL,
    "ProgressPositionTypeId" smallint NOT NULL REFERENCES "ProgressPositionTypes" ("Id"),
    "PositionMs" bigint NULL CHECK ("PositionMs" >= 0),
    "DurationMs" bigint NULL CHECK ("DurationMs" > 0),
    "IsCompleted" boolean NOT NULL DEFAULT FALSE,
    "CompletedAt" timestamptz NULL,
    "Locator" varchar(128) NULL,
    "Progression" numeric(5, 4) NULL CHECK ("Progression" BETWEEN 0 AND 1),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY ("WorkId", "WorkUnitId") REFERENCES "WorkUnits" ("WorkId", "Id") ON DELETE CASCADE,
    CHECK ("ProgressPositionTypeId" <> 1 OR "PositionMs" IS NOT NULL),
    CHECK ("IsCompleted" = ("CompletedAt" IS NOT NULL)),
    CHECK ("ProgressPositionTypeId" <> 2 OR "Locator" IS NOT NULL)
);
CREATE UNIQUE INDEX "UX_MediaProgress_Target" ON "MediaProgress" ("ProfileId", "WorkId", "WorkUnitId") NULLS NOT DISTINCT;
CREATE INDEX "IX_MediaProgress_Recent" ON "MediaProgress" ("ProfileId", "UpdatedAt" DESC, "Id" DESC);

-- A media server user and the profile whose progress it shares. A proposed profile waits for an administrator;
-- a confirmed link without a profile shares nothing.
CREATE TABLE "ProviderProfileLinks" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProviderId" bigint NOT NULL REFERENCES "Providers" ("Id") ON DELETE CASCADE,
    "ExternalUserId" varchar(64) NOT NULL CHECK (length(btrim("ExternalUserId")) > 0),
    "ExternalName" varchar(200) NOT NULL CHECK (length(btrim("ExternalName")) > 0),
    "ProfileId" bigint NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "IsConfirmed" boolean NOT NULL DEFAULT FALSE,
    "SyncedAt" timestamptz NULL,
    UNIQUE ("ProviderId", "ExternalUserId")
);
CREATE UNIQUE INDEX "UX_ProviderProfileLinks_Profile" ON "ProviderProfileLinks" ("ProviderId", "ProfileId") WHERE "IsConfirmed";

-- The state last agreed with a media server per item; whichever side moved since then has changed.
CREATE TABLE "ProviderProgress" (
    "ProviderProfileLinkId" bigint NOT NULL REFERENCES "ProviderProfileLinks" ("Id") ON DELETE CASCADE,
    "ExternalItemId" varchar(64) NOT NULL,
    "PositionMs" bigint NOT NULL CHECK ("PositionMs" >= 0),
    "IsCompleted" boolean NOT NULL,
    "SyncedAt" timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("ProviderProfileLinkId", "ExternalItemId")
);

-- A profile's saves of a game file, opaque to the server: the console's own save memory and one save state.
-- Play time is the game's MediaProgress (type Game, PositionMs played).
CREATE TABLE "GameSaveTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "GameSaveTypes" ("Id", "Key") VALUES (1, 'Memory'), (2, 'State');

CREATE TABLE "GameSaves" (
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "MediaAssetId" bigint NOT NULL REFERENCES "MediaAssets" ("Id") ON DELETE CASCADE,
    "GameSaveTypeId" smallint NOT NULL REFERENCES "GameSaveTypes" ("Id"),
    "Data" bytea NOT NULL CHECK (octet_length("Data") BETWEEN 1 AND 16777216),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("ProfileId", "MediaAssetId", "GameSaveTypeId")
);
CREATE INDEX "IX_GameSaves_MediaAsset" ON "GameSaves" ("MediaAssetId");

-- Active and ended playback; ended sessions are the playback history.
CREATE TABLE "PlaybackModeTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "PlaybackModeTypes" ("Id", "Key") VALUES (1, 'DirectPlay'), (2, 'Remux'), (3, 'Transcode');

CREATE TABLE "PlaybackSessions" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PublicId" uuid NOT NULL UNIQUE,
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "MediaAssetId" bigint NOT NULL REFERENCES "MediaAssets" ("Id") ON DELETE CASCADE,
    "StoredFileId" bigint NOT NULL REFERENCES "StoredFiles" ("Id") ON DELETE CASCADE,
    "PlaybackModeTypeId" smallint NOT NULL REFERENCES "PlaybackModeTypes" ("Id"),
    "PositionMs" bigint NOT NULL DEFAULT 0 CHECK ("PositionMs" >= 0),
    "StartedAt" timestamptz NOT NULL DEFAULT now(),
    "LastSeenAt" timestamptz NOT NULL DEFAULT now(),
    "EndedAt" timestamptz NULL
);
CREATE INDEX "IX_PlaybackSessions_Profile" ON "PlaybackSessions" ("ProfileId", "StartedAt" DESC, "Id" DESC);
CREATE INDEX "IX_PlaybackSessions_Active" ON "PlaybackSessions" ("LastSeenAt") WHERE "EndedAt" IS NULL;

-- Prepared reading content; one document per content and analyzer version, shared by every profile.
CREATE TABLE "ReadingFormatTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "ReadingFormatTypes" ("Id", "Key") VALUES (1, 'Epub'), (2, 'Pdf'), (3, 'Smart'), (4, 'Comic');

CREATE TABLE "ReadingDocuments" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StoredFileId" bigint NULL REFERENCES "StoredFiles" ("Id") ON DELETE SET NULL,
    "SourceSizeBytes" bigint NOT NULL CHECK ("SourceSizeBytes" >= 0),
    "SourceModifiedAt" timestamptz NOT NULL,
    "ContentHash" bytea NOT NULL CHECK (length("ContentHash") = 32),
    "AnalyzerVersion" integer NOT NULL CHECK ("AnalyzerVersion" > 0),
    "ReadingFormatTypeId" smallint NOT NULL REFERENCES "ReadingFormatTypes" ("Id"),
    "Title" varchar(500) NULL,
    "Language" varchar(35) NULL,
    "Structure" jsonb NOT NULL,
    "TotalCharacters" bigint NOT NULL CHECK ("TotalCharacters" >= 0),
    "CacheBytes" bigint NOT NULL DEFAULT 0 CHECK ("CacheBytes" >= 0),
    "CacheCompletedAt" timestamptz NULL,
    "LastReadAt" timestamptz NOT NULL DEFAULT now(),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    UNIQUE ("ContentHash", "AnalyzerVersion")
);
CREATE INDEX "IX_ReadingDocuments_File" ON "ReadingDocuments" ("StoredFileId");
CREATE INDEX "IX_ReadingDocuments_Cache" ON "ReadingDocuments" ("LastReadAt", "Id") WHERE "CacheBytes" > 0;

-- Cached sections and resources; eviction removes rows here only.
CREATE TABLE "ReadingResources" (
    "ReadingDocumentId" bigint NOT NULL REFERENCES "ReadingDocuments" ("Id") ON DELETE CASCADE,
    "Path" varchar(1024) NOT NULL CHECK (length("Path") > 0),
    "MediaType" varchar(128) NOT NULL,
    "Bytes" bytea NOT NULL,
    PRIMARY KEY ("ReadingDocumentId", "Path")
);

-- A profile's highlights and notes in a book file: block and character offsets of the prepared text, the quote stays readable when the book changes.
CREATE TABLE "ReadingAnnotations" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "MediaAssetId" bigint NOT NULL REFERENCES "MediaAssets" ("Id") ON DELETE CASCADE,
    "SectionIndex" integer NOT NULL CHECK ("SectionIndex" >= 0),
    "StartBlock" integer NOT NULL CHECK ("StartBlock" >= 0),
    "StartOffset" integer NOT NULL CHECK ("StartOffset" >= 0),
    "EndBlock" integer NOT NULL CHECK ("EndBlock" >= 0),
    "EndOffset" integer NOT NULL CHECK ("EndOffset" >= 0),
    "Quote" varchar(1000) NOT NULL CHECK (length(btrim("Quote")) > 0),
    "Note" varchar(4000) NULL CHECK (length(btrim("Note")) > 0),
    "HighlightColorTypeId" smallint NOT NULL CHECK ("HighlightColorTypeId" BETWEEN 1 AND 4),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CHECK (("StartBlock", "StartOffset") < ("EndBlock", "EndOffset"))
);
CREATE INDEX "IX_ReadingAnnotations_Asset" ON "ReadingAnnotations" ("ProfileId", "MediaAssetId", "SectionIndex", "StartBlock");

-- The language a profile reads a book in: "original" or a language code; a book without a row follows the profile's language.
CREATE TABLE "ReadingLanguages" (
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "WorkId" bigint NOT NULL REFERENCES "Works" ("Id") ON DELETE CASCADE,
    "Language" varchar(8) NOT NULL CHECK ("Language" = 'original' OR "Language" ~ '^[a-z]{2,3}$'),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("ProfileId", "WorkId")
);

-- What a profile plays by default; a profile without a row plays the file's own audio, shows subtitles while the audio is foreign in the profile's language, at normal speed.
CREATE TABLE "ProfilePlaybackPreferences" (
    "ProfileId" bigint PRIMARY KEY REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    -- Two-letter codes; no audio language keeps the file's default track, no subtitle language follows the profile's language.
    "AudioLanguage" varchar(2) NULL CHECK ("AudioLanguage" ~ '^[a-z]{2}$'),
    "SubtitleLanguage" varchar(2) NULL CHECK ("SubtitleLanguage" ~ '^[a-z]{2}$'),
    -- 1 off, 2 forced only, 3 always, 4 only while the audio is foreign.
    "SubtitleModeTypeId" smallint NOT NULL DEFAULT 4 CHECK ("SubtitleModeTypeId" BETWEEN 1 AND 4),
    "Speed" numeric(3, 2) NOT NULL DEFAULT 1 CHECK ("Speed" BETWEEN 0.5 AND 2),
    "AutoplayNext" boolean NOT NULL DEFAULT TRUE,
    "UpdatedAt" timestamptz NOT NULL DEFAULT now()
);

-- A scanned PDF waiting for text recognition; the worker reads its pages and prepares it like any book. A failed one waits for a changed file.
CREATE TABLE "ReadingRecognitions" (
    "StoredFileId" bigint NOT NULL PRIMARY KEY REFERENCES "StoredFiles" ("Id") ON DELETE CASCADE,
    "SourceSizeBytes" bigint NOT NULL CHECK ("SourceSizeBytes" >= 0),
    "SourceModifiedAt" timestamptz NOT NULL,
    "RequestedAt" timestamptz NOT NULL DEFAULT now(),
    "FailedAt" timestamptz
);

-- How the server converts video: Auto follows the last benchmark's proposal (else the configured arguments), the others fix it.
CREATE TABLE "TranscodeAccelerationTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "TranscodeAccelerationTypes" ("Id", "Key") VALUES (1, 'Auto'), (2, 'Software'), (3, 'Vaapi'), (4, 'Qsv'), (5, 'Nvenc'), (6, 'VideoToolbox');

CREATE TABLE "TranscodeSettings" (
    "Id" bigint PRIMARY KEY CHECK ("Id" = 1),
    "TranscodeAccelerationTypeId" smallint NOT NULL DEFAULT 1 REFERENCES "TranscodeAccelerationTypes" ("Id"),
    -- Conversions at once, counted in 1080p streams; none follows the configuration.
    "MaxTranscodes" smallint NULL CHECK ("MaxTranscodes" BETWEEN 1 AND 64),
    -- Picture heights offered when the server has no room for the wanted conversion.
    "LadderHeights" integer[] NOT NULL DEFAULT '{1080,720,480}' CHECK (cardinality("LadderHeights") <= 6),
    "Version" bigint NOT NULL DEFAULT 1 CHECK ("Version" > 0)
);
INSERT INTO "TranscodeSettings" ("Id") VALUES (1);

-- The last hardware benchmark and what it proposes; a new run replaces it.
CREATE TABLE "TranscodeBenchmarks" (
    "Id" bigint PRIMARY KEY CHECK ("Id" = 1),
    "RanAt" timestamptz NOT NULL,
    "CpuCores" smallint NOT NULL CHECK ("CpuCores" > 0),
    "BestTranscodeAccelerationTypeId" smallint NOT NULL REFERENCES "TranscodeAccelerationTypes" ("Id") CHECK ("BestTranscodeAccelerationTypeId" > 1),
    "RecommendedMaxTranscodes" smallint NOT NULL CHECK ("RecommendedMaxTranscodes" BETWEEN 1 AND 64)
);

-- Seconds of picture converted per second of work; none: the pipeline did not run.
CREATE TABLE "TranscodeBenchmarkResults" (
    "TranscodeBenchmarkId" bigint NOT NULL DEFAULT 1 REFERENCES "TranscodeBenchmarks" ("Id") ON DELETE CASCADE,
    "TranscodeAccelerationTypeId" smallint NOT NULL REFERENCES "TranscodeAccelerationTypes" ("Id") CHECK ("TranscodeAccelerationTypeId" > 1),
    "Height" integer NOT NULL CHECK ("Height" > 0),
    "SpeedFactor" numeric(8, 2) NULL CHECK ("SpeedFactor" >= 0),
    PRIMARY KEY ("TranscodeBenchmarkId", "TranscodeAccelerationTypeId", "Height")
);

COMMIT;
